def get_clause_by_id(clause_id: str):
    return next((art for art in ARTICLES if art["article_id"] == clause_id), None)

def check_compliance_violation(clause_id: str, reported_incident_type: str):
    clause = get_clause_by_id(clause_id)
    if not clause: return False, "Clause not found"
    return True, f"Sanction applied under {clause['penalty_tier']} by {clause['enforcement_officer']}"
